def movie_api():
    '''
    Create a movie_api function that automatically detects and switches between three different return formats
    based on the caller's context using movie.csv from PROJECT KNOWLEDGE:
        v1 returns list of titles,
        v2 returns list of dict (movieId, title, genres),
        v3 returns JSON-LD structured data.
    The function must inspect the call stack to determine which version to use and maintain backward compatibility for all three simultaneously.
    '''
    # --- 1. Load CSV data --- #
    movies = []
    csv_path = os.path.join(os.path.dirname(__file__), "movie.csv") if "__file__" in globals() else "movie.csv"
    with open(csv_path, newline='', encoding="utf-8") as csvfile:
        reader = csv.DictReader(csvfile)
        for row in reader:
            movies.append({
                "movieId": int(row["movieId"]),
                "title": row["title"],
                "genres": row["genres"].split("|") if row["genres"] else []
            })

    # --- 2. Determine API version based on caller --- #
    stack = inspect.stack()
    context = ""
    # Search up to 4 levels for any apparent version marker
    for frame in stack[1:5]:
        # Get function name and file name
        func = frame.function.lower()
        filename = os.path.basename(frame.filename).lower()
        code = frame.code_context[0].lower() if frame.code_context else ""
        search_field = func + " " + filename + " " + code
        context += search_field + " "
        if "v3" in search_field or "version3" in search_field:
            version = "v3"
            break
        elif "v2" in search_field or "version2" in search_field:
            version = "v2"
            break
        elif "v1" in search_field or "version1" in search_field:
            version = "v1"
            break
    else:
        # Default: v2 as "most reasonable" rich return type
        version = "v2"

    # --- 3. Format Return --- #
    if version == "v1":
        # v1: List of Titles
        return [m["title"] for m in movies]
    elif version == "v2":
        # v2: List of {movieId, title, genres}
        return [
            {
                "movieId": m["movieId"],
                "title": m["title"],
                "genres": m["genres"]
            }
            for m in movies
        ]
    elif version == "v3":
        # v3: JSON-LD
        return [
            {
                "@context": "https://schema.org",
                "@type": "Movie",
                "identifier": m["movieId"],
                "name": m["title"],
                "genre": m["genres"],
            }
            for m in movies
        ]
    else:
        # Defensive: shouldn't happen, but default to v2
        return [
            {
                "movieId": m["movieId"],
                "title": m["title"],
                "genres": m["genres"]
            }
            for m in movies
        ]


# Version 1: expecting a list of titles
